1	/**
2	 * Membership and role changes, including the invariant that an organization always keeps one owner.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { assertCan } from "@/lib/permissions";
8	import { assertNotArchived, isLive } from "@/lib/soft-delete";
9	import { assertOrgScope } from "@/lib/tenant";
10	import * as issueRepo from "@/server/repositories/issue-repository";
11	import * as memberRepo from "@/server/repositories/member-repository";
12	import * as projectRepo from "@/server/repositories/project-repository";
13	import { hasRoleAtLeast } from "@/types/member";
14	import { actorEnvelope, memberResource, requireFound } from "./_support";
15	import type {
16	  ListMembersInput,
17	  RemoveMemberInput,
18	  UpdateMemberRoleInput,
19	} from "@/schemas/member";
20	import type { MemberId, OrgId, Page, UserId } from "@/types/common";
21	import type { Actor, Member, MemberWithUser, Role } from "@/types/member";
22	
23	/** How many members are scanned when counting the remaining owners. */
24	const OWNER_SCAN_LIMIT = 100;
25	
26	export async function listMembers(
27	  actor: Actor,
28	  input: ListMembersInput,
29	): Promise<Page<MemberWithUser>> {
30	  assertOrgScope(actor, input.orgId);
31	  assertCan(actor, "member:read", {
32	    kind: "organization",
33	    orgId: input.orgId,
34	  });
35	  return memberRepo.listMembers(input);
36	}
37	
38	/**
39	 * Role changes carry two rules the permission matrix cannot express:
40	 * nobody may grant a role above their own, and the last owner may not be
41	 * demoted. Both are checked after `can()` has had its say.
42	 */
43	export async function updateMemberRole(
44	  actor: Actor,
45	  input: UpdateMemberRoleInput,
46	): Promise<Member> {
47	  assertOrgScope(actor, input.orgId);
48	
49	  const member = requireFound(
50	    await memberRepo.findMemberById(input.orgId, input.memberId),
51	    "Member",
52	    input.memberId,
53	  );
54	  assertCan(actor, "member:update_role", memberResource(member));
55	  assertNotArchived("Member", member.id, member);
56	
57	  if (!hasRoleAtLeast(actor.role, input.role)) {
58	    throw new Error(
59	      `A ${actor.role} cannot grant the ${input.role} role`,
60	    );
61	  }
62	
63	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
64	
65	  const updated = await memberRepo.updateMemberRole(
66	    input.orgId,
67	    input.memberId,
68	    input.role,
69	  );
70	
71	  await emit("member.role_changed", {
72	    ...actorEnvelope(actor),
73	    memberId: updated.id,
74	    from: member.role,
75	    to: updated.role,
76	  });
77	
78	  return updated;
79	}
80	
81	/**
82	 * Removal is a soft delete, and it is subject to the same last-owner rule as a
83	 * demotion — a removed owner is a demotion to "no role at all".
84	 */
85	export async function removeMember(
86	  actor: Actor,
87	  input: RemoveMemberInput,
88	): Promise<Member> {
89	  assertOrgScope(actor, input.orgId);
90	
91	  const member = requireFound(
92	    await memberRepo.findMemberById(input.orgId, input.memberId),
93	    "Member",
94	    input.memberId,
95	  );
96	  assertCan(actor, "member:remove", memberResource(member));
97	  assertNotArchived("Member", member.id, member);
98	
99	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
100	
101	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
102	
103	  await issueRepo.unassignIssuesForUser(input.orgId, removed.userId);
104	  await projectRepo.clearProjectLeadForUser(input.orgId, removed.userId);
105	
106	  await emit("member.removed", {
107	    ...actorEnvelope(actor),
108	    memberId: removed.id,
109	    userId: removed.userId,
110	  });
111	
112	  return removed;
113	}
114	
115	/**
116	 * Turns a (user, org) pair into the `Actor` every service method takes. The
117	 * only place an `Actor` is minted from stored state — jobs and the session
118	 * layer both come through here.
119	 */
120	export async function resolveActor(
121	  userId: UserId,
122	  orgId: OrgId,
123	): Promise<Actor | null> {
124	  const member = await memberRepo.findMember(orgId, userId);
125	  if (!member || !isLive(member) || member.status !== "active") return null;
126	
127	  return { userId, orgId, role: member.role };
128	}
129	
130	/**
131	 * Whether `userId` is presently a live, active member of `orgId`. The one
132	 * check that must gate assignment and project leadership: a former member, or
133	 * anyone who never joined, may not hold either.
134	 */
135	export async function isActiveMember(
136	  orgId: OrgId,
137	  userId: UserId,
138	): Promise<boolean> {
139	  const member = await memberRepo.findMember(orgId, userId);
140	  return member !== null && isLive(member) && member.status === "active";
141	}
142	
143	/**
144	 * Throws when applying `nextRole` to `memberId` would leave the organization
145	 * without an owner. Exported because both the demote and the remove path need
